function tr(key, lang, vars) {
  let e = I18N[key];
  let k = key;
  // Match cv_builder.py tr(): labels built as "Something:" use the bare key.
  if (!e && typeof key === 'string' && key.endsWith(':')) {
    k = key.slice(0, -1);
    e = I18N[k];
  }
  let v = e ? (e[lang] || e.en || k) : k;
  if (typeof v === 'string') {
    v = v.replace(/\{(\w+)\}/g, (m, n) => (vars && vars[n] != null) ? vars[n] : m);
  }
  return v;
}
